const readPref = async () => {
  try {
    if (typeof window === "undefined") return null;
    if (window.storage && window.storage.get) { const r = await window.storage.get(PREF_KEY); return r && r.value ? JSON.parse(r.value) : null; }
    if (window.localStorage) { const v = window.localStorage.getItem(PREF_KEY); return v ? JSON.parse(v) : null; }
  } catch (e) { /* nothing saved yet */ }
  return null;
};
const writePref = (obj) => {
  try {
    if (typeof window === "undefined") return;
    const v = JSON.stringify(obj);
    if (window.storage && window.storage.set) window.storage.set(PREF_KEY, v);
    else if (window.localStorage) window.localStorage.setItem(PREF_KEY, v);
  } catch (e) { /* storage is not available */ }
};
