/* a dropdown with its label at the top left */
function CtlField({ label, children }) {
  return (<div className="hvs-cf"><span className="hvs-cf-l">{label}</span>{children}</div>);
}
/* how a long list is handled; the combined options are offered but flagged Avoid */
const ROW_COUNTS = [3, 5, 7, 40];
const LIST_MODES = [["none", "None"], ["pagination", "Pagination"], ["hscroll", "Horizontal scroll"], ["vscroll", "Vertical scroll"], ["pagination-hscroll", "Pagination and horizontal scroll", "Avoid"], ["pagination-vscroll", "Pagination and vertical scroll", "Avoid"]];
const LIST_PATCH = {
  none: { showPagination: false, scrollbarHorizontal: false, scrollbarVertical: false },
  pagination: { showPagination: true, scrollbarHorizontal: false, scrollbarVertical: false },
  hscroll: { showPagination: false, scrollbarHorizontal: true, scrollbarVertical: false }, // sideways scroll only: every row shows, no vertical scroll
  vscroll: { showPagination: false, scrollbarHorizontal: false, scrollbarVertical: true },
  "pagination-hscroll": { showPagination: true, scrollbarHorizontal: true, scrollbarVertical: false },
  "pagination-vscroll": { showPagination: true, scrollbarHorizontal: false, scrollbarVertical: true },
};
const listModeOf = (c) => {
  const key = `${c.showPagination ? "p" : ""}${c.scrollbarHorizontal ? "h" : ""}${c.scrollbarVertical ? "v" : ""}`;
  return { "": "none", p: "pagination", h: "hscroll", v: "vscroll", ph: "pagination-hscroll", pv: "pagination-vscroll" }[key] || "custom";
};

/* the Filter button of the Header group has two parts: "Filter:" turns the filter on or off,
   the type ("Group" or "MUI") opens the choice of type below it (the current type is disabled);
   picking a type while the filter is off also turns it on */
const FILTER_TYPES = [["group", "Group"], ["rows", "MUI"]];
function FilterHeaderBtn({ on, type, onPick, onOff, onOn }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const out = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", out);
    document.addEventListener("keydown", esc);
    const first = ref.current && ref.current.querySelector(".hvs-fopt:not(:disabled)");
    if (first) first.focus();
    return () => { document.removeEventListener("mousedown", out); document.removeEventListener("keydown", esc); };
  }, [open]);
  const name = (FILTER_TYPES.find((t) => t[0] === type) || FILTER_TYPES[0])[1];
  return (
    <span className="hvs-fwrap" ref={ref}>
      <button type="button" className="hvs-segbtn hvs-fpart is-a" aria-pressed={on} onClick={() => (on ? onOff() : onOn())}>Filter:</button>
      <span className="hvs-ftype">
      <button type="button" className="hvs-segbtn hvs-fpart is-b" aria-pressed={on} aria-haspopup="menu" aria-expanded={open}
              aria-label={`Filter type: ${name}`} onClick={() => setOpen((o) => !o)}><span className="hvs-fname">{FILTER_TYPES.map(([v, t]) => (<span key={v} aria-hidden={v !== type} style={{ visibility: v === type ? "visible" : "hidden" }}>{t}</span>))}</span><span className="hvs-fcaret" aria-hidden="true"><svg viewBox="0 0 10 6"><path d="M0 0h10L5 6z" fill="currentColor" /></svg></span></button>
      {open && (
        <span className="hvs-fpop" role="menu" aria-label="Filter type">
          {FILTER_TYPES.map(([v, t]) => (
            <button key={v} type="button" role="menuitemradio" aria-checked={v === type} disabled={v === type} className="hvs-fopt"
                    onClick={() => { setOpen(false); onPick(v); }}><span>{t}</span>{v === type ? <span className="hvs-fcheck" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg></span> : null}</button>
          ))}
        </span>
      )}
      </span>
    </span>
  );
}

/* a single-choice control of the control bar, built like the filter type block ("Group"): one raised block in the grey track,
   its value plus a caret; the menu hangs from the track, aligned to the block, with a check on the current value */
function CtlSelect({ value, options, onPick, ariaLabel }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return undefined;
    const out = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", out);
    document.addEventListener("keydown", esc);
    const first = ref.current && ref.current.querySelector(".hvs-fopt:not(:disabled)");
    if (first) first.focus();
    return () => { document.removeEventListener("mousedown", out); document.removeEventListener("keydown", esc); };
  }, [open]);
  const cur = options.find((o) => o.value === value);
  const shown = cur ? options : [...options, { value, label: "Custom" }];
  return (
    <span className="hvs-seg hvs-selseg" ref={ref}>
      <span className="hvs-ftype">
        <button type="button" className="hvs-segbtn hvs-fpart is-b is-solo" aria-pressed="true" aria-haspopup="menu" aria-expanded={open}
                aria-label={`${ariaLabel}: ${cur ? cur.label : "Custom"}`} onClick={() => setOpen((o) => !o)}>
          <span className="hvs-fname">{shown.map((o) => (<span key={String(o.value)} aria-hidden={o.value !== value} style={{ visibility: o.value === value ? "visible" : "hidden" }}>{o.label}</span>))}</span>
          <span className="hvs-fcaret" aria-hidden="true"><svg viewBox="0 0 10 6"><path d="M0 0h10L5 6z" fill="currentColor" /></svg></span>
        </button>
        {open && (
          <span className="hvs-fpop" role="menu" aria-label={ariaLabel}>
            {options.map((o) => (
              <button key={String(o.value)} type="button" role="menuitemradio" aria-checked={o.value === value} disabled={o.value === value} className="hvs-fopt"
                      onClick={() => { setOpen(false); onPick(o.value); }}>
                <span>{o.label}{o.tag ? <span className="hvs-ftag">{o.tag}</span> : null}</span>
                {o.value === value ? <span className="hvs-fcheck" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none"><path d="M3.5 8.5l3 3 6-7" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" /></svg></span> : null}
              </button>
            ))}
          </span>
        )}
      </span>
    </span>
  );
}

function Check({ label, checked, onChange, disabled }) {
  return (
    <label className="hvs-check">
      <input type="checkbox" checked={checked} disabled={disabled} onChange={(e) => onChange(e.target.checked)} />
      {label}
    </label>
  );
}

function Seg({ label, value, options, onChange }) {
  return (
    <div className="hvs-field" role="group" aria-label={label}>
      <span className="hvs-lbl">{label}</span>
      <div className="hvs-seg">
        {options.map(([val, text, off]) => (
          <button key={val} type="button" className="hvs-segbtn" aria-pressed={value === val} disabled={!!off}
                  onClick={() => onChange(val)}>{text}</button>
        ))}
      </div>
    </div>
  );
}

