/* ---------- Tags: the TAG component of the library (Status and Categorical) ---------- */
const TAG_STATUS = [["positive", "Positive", "Normal"], ["warning", "Warning", "Warning"], ["negative", "Negative", "Critical"], ["info", "Info", "Info"]];
const tagStatusIcon = (k) => (k === "negative" ? Icons.StatusCritical : k === "warning" ? Icons.StatusWarning : k === "info" ? Icons.StatusInfo : Icons.StatusGood);
function TagView({ type, kind, cat, text }) {
  if (type === "status") {
    return (
      <span className={`hvt-tag is-status is-${kind}`}>
        <span className="hvt-tag-label"><span className="hvt-tag-body">
          <i className="hvt-tag-ico" aria-hidden="true">{tagStatusIcon(kind)}</i><span className="hvt-tag-text">{text}</span>
        </span></span>
      </span>
    );
  }
  return (
    <span className="hvt-tag is-cat" style={{ "--tag-fill": `var(--cat${cat}-20)`, "--tag-stroke": `var(--cat${cat}-140)` }}>
      <span className="hvt-tag-label"><span className="hvt-tag-body"><span className="hvt-tag-text">{text}</span></span></span>
    </span>
  );
}
function TagsBench({ theme, onTheme }) {
  const [c, setC] = useState({ type: "status", kind: "positive", cat: 7, size: "default", show: "one", label: "" });
  const set = (p) => setC((x) => ({ ...x, ...p }));
  const statusText = (k) => (TAG_STATUS.find((x) => x[0] === k) || TAG_STATUS[0])[2];
  const text = (type, kind, cat) => c.label.trim() || (type === "status" ? statusText(kind) : `Category ${cat}`);
  return (
    <>
      <div className="hvs-ctl">
        <div className="hvs-databar" role="toolbar" aria-label="Tag controls">
          <ThemeSeg theme={theme} onTheme={onTheme} />
          <BenchSeg label="Type" value={c.type} onChange={(v) => set({ type: v })} options={[["status", "Status"], ["cat", "Categorical"]]} />
          {c.type === "status" ? (
            <BenchSeg label="Status" value={c.kind} onChange={(v) => set({ kind: v })} options={TAG_STATUS.map(([v, t]) => [v, t])} />
          ) : (
            <CtlField label="Category">
              <MenuButton variant="ghost" role="listbox" ariaLabel="Category" value={c.cat} label={String(c.cat)} minWidth={120}
                          items={Array.from({ length: 12 }, (_, i) => ({ value: i + 1, label: String(i + 1) }))} onSelect={(it) => set({ cat: it.value })} />
            </CtlField>
          )}
          <BenchSeg label="Density" value={c.size} onChange={(v) => set({ size: v })} options={[["default", "Default"], ["compact", "Compact"]]} />
          <BenchSeg label="Show" value={c.show} onChange={(v) => set({ show: v })} options={[["one", "One tag"], ["all", "All tags"]]} />
          <CtlField label="Label">
            <input className="hvs-input" type="text" value={c.label} placeholder="Default label" aria-label="Label" onChange={(e) => set({ label: e.target.value })} />
          </CtlField>
        </div>
      </div>
      <div className="hvs-benchstage hvt-scope" data-theme={theme}>
        <style>{CSS}</style>
        <div className={`hvt-root${c.size === "compact" ? " is-compact" : ""}`} style={{ padding: 16 }}>
          {c.show === "one" ? (
            <div className="hvs-tagrow"><TagView type={c.type} kind={c.kind} cat={c.cat} text={text(c.type, c.kind, c.cat)} /></div>
          ) : (
            <div className="hvs-taggroups">
              <div className="hvs-tagrow">{TAG_STATUS.map(([k]) => (<TagView key={k} type="status" kind={k} text={text("status", k)} />))}</div>
              <div className="hvs-tagrow">{Array.from({ length: 12 }, (_, i) => (<TagView key={i} type="cat" cat={i + 1} text={text("cat", null, i + 1)} />))}</div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

/* ---------- Search: the quick filter used by the table (SEARCH in the library) ---------- */
function SearchBench({ theme, onTheme }) {
  const [c, setC] = useState({ mode: "persistent", state: "enabled", suggest: true, recent: true, placeholder: "Search...", errorText: "Error message." });
  const set = (p) => setC((x) => ({ ...x, ...p }));
  const [value, setValue] = useState("");
  const [expanded, setExpanded] = useState(true);
  const [submitted, setSubmitted] = useState("");
  const [recents, setRecents] = useState(SEARCH_RECENT["vsp-systems"]);
  useEffect(() => { setExpanded(c.mode === "persistent"); }, [c.mode]);
  const pool = useMemo(() => {
    const d = dsById("vsp-systems"), set2 = new Set();
    d.rows.forEach((r) => d.columns.forEach((col) => { const v = r[col.key]; if (typeof v === "string" && v.length > 1) set2.add(v); }));
    return [...set2];
  }, []);
  return (
    <>
      <div className="hvs-ctl">
        <div className="hvs-databar" role="toolbar" aria-label="Search controls">
          <ThemeSeg theme={theme} onTheme={onTheme} />
          <BenchSeg label="Behavior" value={c.mode} onChange={(v) => set({ mode: v })} options={[["persistent", "Always open"], ["expandable", "Expands"]]} />
          <BenchSeg label="State" value={c.state} onChange={(v) => set({ state: v })} options={[["enabled", "Enabled"], ["disabled", "Disabled"], ["error", "Error"]]} />
          <CtlField label="List">
            <div className="hvs-seg" role="group" aria-label="List (select several)">
              <button type="button" className="hvs-segbtn" aria-pressed={c.suggest} onClick={() => set({ suggest: !c.suggest })}>Suggestions</button>
              <button type="button" className="hvs-segbtn" aria-pressed={c.recent} onClick={() => set({ recent: !c.recent })}>Recent searches</button>
            </div>
          </CtlField>
          <CtlField label="Placeholder">
            <input className="hvs-input" type="text" value={c.placeholder} aria-label="Placeholder" onChange={(e) => set({ placeholder: e.target.value })} />
          </CtlField>
          {c.state === "error" && (
            <CtlField label="Error message">
              <input className="hvs-input" type="text" value={c.errorText} aria-label="Error message" onChange={(e) => set({ errorText: e.target.value })} />
            </CtlField>
          )}
        </div>
      </div>
      <div className="hvs-benchstage hvt-scope" data-theme={theme}>
        <style>{CSS}</style>
        <div className="hvt-root hvs-searchroot" style={{ padding: 16 }}>
          <div className="hvt-titlebar" style={{ padding: 0 }}>
            <h3 className="hvt-title">Storage Systems</h3>
            <div className="hvt-actions-bar">
              <div className="hvt-sf">
                <QuickFilter value={value} onChange={setValue} onSubmit={(t) => setSubmitted((t === undefined ? value : t).trim())}
                             mode={c.mode} expanded={expanded} onExpandedChange={setExpanded} placeholder={c.placeholder}
                             suggestions={c.suggest ? pool : []} recents={c.recent ? recents : []}
                             onRecent={(t) => setRecents((p) => [t, ...p.filter((x) => x.toLowerCase() !== t.toLowerCase())].slice(0, 5))}
                             disabled={c.state === "disabled"} error={c.state === "error" ? c.errorText : ""} />
              </div>
            </div>
          </div>
          <p className="hvt-muted hvs-searchout" aria-live="polite">{submitted ? `Searching for "${submitted}".` : "Type to see suggestions. Enter or View All Results searches."}</p>
        </div>
      </div>
    </>
  );
}

export default function App() {
  const [cfg, setCfg] = useState(DEFAULT_CFG);
  const [page, setPage] = useState("table"); // workbench page: table, tags or search
  const [open, setOpen] = useState(DEFAULT_OPEN);
  const [resetKey, setResetKey] = useState(0);
  const [startModel, setStartModel] = useState(EMPTY_MODEL);
  const [last, setLast] = useState("No action yet");
  const [model, setModel] = useState(EMPTY_MODEL);
  const [colOrder, setColOrder] = useState(null);
  const [colWidths, setColWidths] = useState({});
  const [colConfig, setColConfig] = useState(null);
  const [addChoice, setAddChoice] = useState("text");
  const [dataRows, setDataRows] = useState(dsById(INITIAL_DS).rows.slice(0, 40));
  const stageRef = useRef(null);
  const rzRef = useRef(null);
  const [rzActive, setRzActive] = useState(false);
  const [errorShown, setErrorShown] = useState(false); // the error banner arrives 5 s after the table renders
  const [errorLeft, setErrorLeft] = useState(0);
  const [errorSeen, setErrorSeen] = useState(false); // the banner has already come in this round
  const errTimerRef = useRef(null);
  const legacySide = typeof window !== "undefined" && !!window.__HVS_SIDE__; // test hook: the old always-open left column
  const [varsTab, setVarsTab] = useState(legacySide ? "settings" : "colors"); // the Variables panel: colors, spacing or the remaining settings
  const [sideOpen, setSideOpen] = useState(() => typeof window !== "undefined" && !!window.__HVS_SIDE__); // Exploration starts collapsed (window.__HVS_SIDE__ is a test hook)
  const [cfgOpen, setCfgOpen] = useState(true); // Configuration starts open
  const prefReady = useRef(legacySide);
  useEffect(() => {
    if (legacySide) return undefined;
    let alive = true;
    readPref().then((pf) => {
      if (!alive) return;
      if (pf) { if (typeof pf.open === "boolean") setSideOpen(pf.open); if (["colors", "spacing", "settings"].includes(pf.tab)) setVarsTab(pf.tab); }
      prefReady.current = true;
    });
    return () => { alive = false; };
  }, []); // eslint-disable-line
  useEffect(() => { if (prefReady.current) writePref({ open: sideOpen, tab: varsTab }); }, [sideOpen, varsTab]);
  const [rzvTip, setRzvTip] = useState(null); // while dragging the height: { n, px }
  const rzvRef = useRef(null);
  const canvasRef = useRef(null);
  const [maxOn, setMaxOn] = useState(false);

  const toggle = (id) => setOpen((o) => ({ ...o, [id]: !o[id] }));
  const setAll = (v) => setOpen(Object.fromEntries(ALL_OPEN_IDS.map((id) => [id, v])));
  const set = (patch) =>
    setCfg((c) => {
      const n = { ...c, ...patch };
      // pagination and vertical scroll are not used together: turning one on turns the other off
      if (patch.showPagination === true && !("scrollbarVertical" in patch)) n.scrollbarVertical = false;
      if (patch.scrollbarVertical === true && !("showPagination" in patch)) n.showPagination = false;
      return n;
    });
  const setCol = (key, patch) => setCfg((c) => ({ ...c, cols: { ...c.cols, [key]: { ...c.cols[key], ...patch } } }));
  const setSize = (size) =>
    setCfg((c) => ({
      ...c, size,
      selectable: size === "compact" ? false : c.selectable,
      expandable: size === "compact" ? false : c.expandable,
    }));
  const setTok = (theme, name, value) =>
    setCfg((c) => {
      const cur = { ...c.tokens[theme] };
      if (value === null) delete cur[name]; else cur[name] = value;
      return { ...c, tokens: { ...c.tokens, [theme]: cur } };
    });

  const ds = dsById(cfg.dataset);
  const tableWidth = cfg.widthMode === "grid" ? spanWidth(cfg.gridCanvas, cfg.gridSpan) : FRAME_WIDTH;
  const spanFor = (w) => {
    let best = MIN_SPAN, dist = Infinity;
    for (let n = MIN_SPAN; n <= GRID.columns; n++) { const d = Math.abs(spanWidth(cfg.gridCanvas, n) - w); if (d < dist) { dist = d; best = n; } }
    return best;
  };
  const spanNow = cfg.widthMode === "grid" ? cfg.gridSpan : spanFor(FRAME_WIDTH);
  /* on the layout grid the table starts on a column edge: centred when the free columns split evenly,
     otherwise one more free column on the right (never half a column off) */
  const gridCol = (cfg.gridCanvas - 2 * GRID.margin - (GRID.columns - 1) * GRID.gutter) / GRID.columns;
  const gridStart = Math.floor((GRID.columns - spanNow) / 2);
  const gridPlace = cfg.widthMode === "grid"
    ? { marginLeft: `calc(50% - ${cfg.gridCanvas / 2}px + ${Math.round(GRID.margin + gridStart * (gridCol + GRID.gutter))}px)`, marginRight: "auto" }
    : {};
  const rzDown = (e) => {
    e.preventDefault();
    const r = stageRef.current.getBoundingClientRect();
    rzRef.current = { id: e.pointerId, cx: (r.left + r.right) / 2 };
    e.currentTarget.setPointerCapture(e.pointerId);
    setRzActive(true);
  };
  const rzMove = (e) => {
    const d = rzRef.current;
    if (!d || d.id !== e.pointerId) return;
    const n = spanFor(2 * Math.abs(e.clientX - d.cx));
    if (cfg.widthMode !== "grid" || cfg.gridSpan !== n) set({ widthMode: "grid", gridSpan: n });
  };
  const rzUp = (e) => {
    const d = rzRef.current;
    if (!d || d.id !== e.pointerId) return;
    try { e.currentTarget.releasePointerCapture(e.pointerId); } catch (err) { /* released */ }
    rzRef.current = null;
    setRzActive(false);
  };
  /* height, counted in rows: with pagination it sets the rows per page, with scroll the visible rows */
  const rowsMode = cfg.heightMode === "rows";
  const effPageSize = rowsMode && cfg.showPagination ? cfg.heightRows : cfg.pageSize;
  const effVScroll = cfg.scrollbarVertical || (rowsMode && !cfg.showPagination);
  const effVisible = rowsMode ? cfg.heightRows : cfg.visibleRows;
  const rowsNow = rowsMode ? cfg.heightRows : cfg.showPagination ? cfg.pageSize : cfg.scrollbarVertical ? cfg.visibleRows : null;
  const MIN_ROWS = 2, MAX_ROWS = 20;
  const lastRows = useRef(null); // the last number of rows on show (rows per page, or visible rows)
  if (rowsNow) lastRows.current = rowsNow;
  const measureRowsGeo = () => {
    const root = stageRef.current.querySelector(".hvt-root");
    const rowsEl = root && root.querySelector(".hvt-rows");
    const stage = stageRef.current.getBoundingClientRect();
    const cs = getComputedStyle(root);
    const joinedNow = root.classList.contains("is-joined");
    const rects = rowsEl ? Array.from(rowsEl.children).filter((c) => c.classList.contains("hvt-group")).map((el) => el.getBoundingClientRect()) : [];
    let h = parseFloat(cs.getPropertyValue("--hvt-row-h")) || 48;
    let gap = joinedNow ? 1 : parseFloat(cs.getPropertyValue("--hvt-row-gap")) || 12;
    let overhead = joinedNow ? 13 : 0;
    if (rects.length) {
      h = Math.max(...rects.map((r) => r.height));
      if (rects.length > 1) gap = Math.max(0, Math.max(...rects.slice(1).map((r, i) => r.top - rects[i].bottom)));
      overhead = rects[0].top - rowsEl.getBoundingClientRect().top + (parseFloat(getComputedStyle(rowsEl).paddingBottom) || 0);
    }
    const n = rowsNow ?? Math.max(1, rects.length);
    return { h, gap, overhead, chrome0: stage.height - (n * h + (n - 1) * gap + overhead) };
  };
  const heightFor = (m, n) => Math.round(m.chrome0 + m.overhead + n * m.h + (n - 1) * m.gap);
  const rzvDown = (e) => {
    e.preventDefault();
    const r = stageRef.current.getBoundingClientRect();
    rzvRef.current = { id: e.pointerId, cy: (r.top + r.bottom) / 2, m: measureRowsGeo() };
    if (canvasRef.current) canvasRef.current.style.minHeight = `${canvasRef.current.getBoundingClientRect().height}px`; // the centre stays put while dragging
    e.currentTarget.setPointerCapture(e.pointerId);
    setRzvTip({ n: rowsNow ?? 0, px: Math.round(r.height) });
  };
  const rzvMove = (e) => {
    const d = rzvRef.current;
    if (!d || d.id !== e.pointerId) return;
    const target = 2 * Math.abs(e.clientY - d.cy);
    const n = Math.max(MIN_ROWS, Math.min(MAX_ROWS, Math.round((target - d.m.chrome0 - d.m.overhead + d.m.gap) / (d.m.h + d.m.gap))));
    setRzvTip({ n, px: heightFor(d.m, n) });
    if (cfg.heightMode !== "rows" || cfg.heightRows !== n) set({ heightMode: "rows", heightRows: n });
  };
  const rzvUp = (e) => {
    const d = rzvRef.current;
    if (!d || d.id !== e.pointerId) return;
    try { e.currentTarget.releasePointerCapture(e.pointerId); } catch (err) { /* released */ }
    rzvRef.current = null;
    if (canvasRef.current) canvasRef.current.style.minHeight = "";
    setRzvTip(null);
  };
  const rzvKey = (e) => {
    const cur = rowsNow ?? 8;
    const step = { ArrowUp: 1, ArrowRight: 1, ArrowDown: -1, ArrowLeft: -1 }[e.key];
    if (step !== undefined) { e.preventDefault(); set({ heightMode: "rows", heightRows: Math.max(MIN_ROWS, Math.min(MAX_ROWS, cur + step)) }); }
    else if (e.key === "Home") { e.preventDefault(); set({ heightMode: "rows", heightRows: MIN_ROWS }); }
    else if (e.key === "End") { e.preventDefault(); set({ heightMode: "rows", heightRows: MAX_ROWS }); }
  };
  const rzKey = (e) => {
    const step = { ArrowRight: 1, ArrowUp: 1, ArrowLeft: -1, ArrowDown: -1 }[e.key];
    if (step !== undefined) { e.preventDefault(); set({ widthMode: "grid", gridSpan: Math.max(MIN_SPAN, Math.min(GRID.columns, spanNow + step)) }); }
    else if (e.key === "Home") { e.preventDefault(); set({ widthMode: "grid", gridSpan: MIN_SPAN }); }
    else if (e.key === "End") { e.preventDefault(); set({ widthMode: "grid", gridSpan: GRID.columns }); }
  };
  useEffect(() => {
    setErrorShown(false);
    setErrorSeen(false);
    if (cfg.tableState !== "error") { setErrorLeft(0); return undefined; }
    let left = 5;
    setErrorLeft(left);
    const iv = setInterval(() => {
      left -= 1;
      setErrorLeft(Math.max(0, left));
      if (left <= 0) { clearInterval(iv); setErrorShown(true); setErrorSeen(true); }
    }, 1000);
    errTimerRef.current = iv;
    return () => clearInterval(iv);
  }, [cfg.tableState, cfg.dataset, resetKey]);
  /* the banner can also be called early: one click anywhere on the canvas or the table */
  const triggerError = () => {
    if (cfg.tableState !== "error" || errorSeen) return;
    clearInterval(errTimerRef.current);
    setErrorLeft(0);
    setErrorShown(true);
    setErrorSeen(true);
  };
  const placeholder = !!ds.pool;
  const baseColumns = useMemo(
    () => [...ds.columns, ...cfg.added.map((k) => COL_LOOKUP[k]).filter(Boolean)],
    [ds, cfg.added]
  );
  const visibleCount = baseColumns.filter((c) => cfg.cols[c.key] && cfg.cols[c.key].visible).length;
  const baseCount = ds.columns.length;
  const availableFields = ds.extra.filter((f) => !cfg.added.includes(f.key));
  const placeholderChoice = addChoice === "number" ? "number" : "text";
  const realisticChoice = availableFields.some((f) => f.key === addChoice) ? addChoice : (availableFields[0] || {}).key;
  const nextPoolKey = (pool) => pool.map((c) => c.key).find((k) => !cfg.added.includes(k));
  const canAdd = placeholder ? !!nextPoolKey(placeholderChoice === "number" ? NUMBER_POOL : TEXT_POOL) : availableFields.length > 0;
  const addColumn = () => {
    const key = placeholder ? nextPoolKey(placeholderChoice === "number" ? NUMBER_POOL : TEXT_POOL) : realisticChoice;
    if (!key) return;
    setCfg((c) => ({ ...c, added: [...c.added, key], cols: { ...c.cols, [key]: { ...c.cols[key], visible: true } } }));
  };
  const removeColumn = (key) => setCfg((c) => ({ ...c, added: c.added.filter((k) => k !== key) }));
  const setAllCols = (visible) =>
    setCfg((c) => ({ ...c, cols: Object.fromEntries(Object.entries(c.cols).map(([k, v]) => [k, { ...v, visible }])) }));

  const columns = useMemo(
    () =>
      baseColumns.filter((c) => cfg.cols[c.key] && cfg.cols[c.key].visible).map((c) => ({
        ...c,
        title: cfg.cols[c.key].title.trim() || c.title,
        sortable: cfg.cols[c.key].sortable,
      })),
    [baseColumns, cfg.cols]
  );
  const pinnedKeys = useMemo(() => columns.slice(0, cfg.fixedCount).map((c) => c.key), [columns, cfg.fixedCount]);
  const typeName = cfg.selectable && cfg.expandable ? "Expandable + Selectable" : cfg.selectable ? "Selectable" : cfg.expandable ? "Expandable" : "Simple";

  const tokenStyle = cfg.tokens[cfg.theme];
  const layoutVars = {
    "--hvt-colgap": `${cfg.colGap}px`, "--hvt-cellpad": `${cfg.cellPad}px`, "--hvt-rowpad": `${cfg.rowPad}px`, "--hvt-tablepad": `${cfg.tablePad}px`,
    ...(cfg.rowH ? { "--hvt-row-h": `${cfg.rowH}px` } : {}), ...(cfg.headH ? { "--hvt-head-h": `${cfg.headH}px` } : {}),
  };
  const tokenValue = (name) => tokenStyle[name] ?? TOKEN_DEFAULTS[cfg.theme][name] ?? SHAPE_DEFAULTS[name];
  const tokenDef = (name) => TOKEN_DEFAULTS[cfg.theme][name] ?? SHAPE_DEFAULTS[name];
  const changedCount = Object.keys(tokenStyle).length;
  const changedIn = (names) => names.filter((n) => tokenStyle[n] !== undefined).length;

  const saveChoice = (id) => { try { if (typeof window !== "undefined" && window.storage && !window.__HVS_DATASET__) window.storage.set("hvs:dataset", id); } catch (err) { /* storage is optional */ } };
  const switchDataset = (id, patch = {}, rows) => {
    const d = dsById(id);
    saveChoice(id);
    setCfg((c) => ({ ...c, ...patch, dataset: id, added: [], cols: initCols(d), titleText: null }));
    setDataRows((rows || d.rows).slice(0, cfg.rowCount)); // the chosen number of rows follows the dataset
    setStartModel(EMPTY_MODEL);
    setModel(EMPTY_MODEL);
    setColOrder(null);
    setColWidths({});
    setColConfig(null);
    setResetKey((k) => k + 1);
  };
  const reset = () => {
    setCfg({ ...DEFAULT_CFG, dataset: cfg.dataset, rowCount: cfg.rowCount, cols: initCols(ds) }); // the chosen dataset (and its rows) stay
    setOpen(DEFAULT_OPEN);
    setStartModel(EMPTY_MODEL);
    setModel(EMPTY_MODEL);
    setLast("No action yet");
    setColOrder(null);
    setColWidths({});
    setColConfig(null);
    setResetKey((k) => k + 1);
  };
  const loadExampleFilters = () => {
    const m = exampleModel(cfg.dataset); // examples for the dataset you are on; the dataset does not change
    setCfg((c) => ({ ...c, showFilterBar: true }));
    setStartModel(m);
    setModel(m);
    setResetKey((k) => k + 1);
  };

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        if (typeof window === "undefined" || !window.storage || window.__HVS_DATASET__) return;
        const r = await window.storage.get("hvs:dataset");
        const id = r && r.value;
        if (alive && id && id !== cfg.dataset && PRODUCT_DATASETS.some((d) => d.id === id)) switchDataset(id);
      } catch (err) { /* nothing saved yet */ }
    })();
    return () => { alive = false; };
  }, []);

  const readout = {
    global: { product: PRODUCTS.find((p) => p.id === cfg.product).label, component: COMPONENTS.find((c) => c.id === cfg.component).label, designSystemVersion: VERSIONS.find((v) => v.id === cfg.version).label, theme: THEMES.find((t) => t[0] === cfg.theme)[1] },
    component: {
      Size: SIZES.find((o) => o[0] === cfg.size)[1], Type: typeName, title: cfg.showTitle, filterBar: cfg.showFilterBar,
      pagination: cfg.showPagination, scrollbarHorizontal: cfg.scrollbarHorizontal, scrollbarVertical: cfg.scrollbarVertical,
      maximize: cfg.showMaximize, moreOptions: cfg.showMoreOptions,
    },
    features: {
      search: cfg.searchEnabled ? cfg.searchMode : false, filterUi: cfg.filterUi, filterPanelStyle: cfg.filterPanelStyle, width: cfg.widthMode === "grid" ? `${cfg.gridSpan} of 12 columns on ${cfg.gridCanvas}px (${tableWidth}px)` : "Figma frame 800px", rowEditing: cfg.editable,
      columnReorder: cfg.columnReorder, columnResize: cfg.columnResize, fixedColumns: pinnedKeys,
      visibleRows: cfg.visibleRows, columnMinWidth: cfg.columnMinWidth, rowsPerPage: cfg.pageSize,
    },
  };

  return (
    <div className="hvs hvt-scope" data-theme={cfg.theme}>
      <style>{SCREEN_CSS}</style>

      <div className="hvs-head">
        <h1 className="hvs-h1">Workbench: <PageSwitch page={page} onPick={setPage} /></h1>
      </div>

      {page === "table" ? (<>
      <div className="hvs-grid is-solo">

        <main className="hvs-main">
          <section className="hvs-sec" aria-label="Configuration">
          <div className="hvs-ctl">
            <div className="hvs-databar" role="toolbar" aria-label="Table controls">
              <CtlField label="Theme">
              <div className="hvs-seg hvs-pill" role="group" aria-label="Theme">
                <button type="button" className="hvs-segbtn hvs-pill-b is-dawn" aria-pressed={cfg.theme === "dawn"} onClick={() => set({ theme: "dawn" })}>Dawn</button>
                <button type="button" className="hvs-segbtn hvs-pill-b is-wicked" aria-pressed={cfg.theme === "wicked"} onClick={() => set({ theme: "wicked" })}>Wicked</button>
              </div>
              </CtlField>
              <CtlField label="Header">
                <div className="hvs-seg" role="group" aria-label="Header (select several)">
                  {[["showTitle", "Title"], ["searchEnabled", "Search"], ["showFilterButton", "Filter"], ["showFilterBar", "Filter bar"], ["showAddButton", "Button"], ["showMaximize", "Maximize"], ["showMoreOptions", "More options"]].map(([key, label]) => {
                    const on = !!cfg[key];
                    if (key === "showFilterButton") return (
                      <FilterHeaderBtn key={key} on={on} type={cfg.filterUi} onOff={() => set({ showFilterButton: false })} onOn={() => set({ showFilterButton: true })}
                                       onPick={(v) => set({ showFilterButton: true, filterUi: v })} />
                    );
                    const blocked = key === "showAddButton" && !cfg.editable; // the add button belongs to the row editing
                    return (
                      <button key={key} type="button" className="hvs-segbtn" aria-pressed={on} disabled={blocked}
                              title={blocked ? "Turn on Add, Edit and Delete rows to use the button" : undefined} onClick={() => set({ [key]: !on })}>{label}</button>
                    );
                  })}
                </div>
              </CtlField>
              <CtlField label="Density">
                <div className="hvs-seg" role="group" aria-label="Density">
                  {SIZES.map(([value, label]) => (
                    <button key={value} type="button" className="hvs-segbtn" aria-pressed={cfg.size === value} onClick={() => setSize(value)}>{label}</button>
                  ))}
                </div>
              </CtlField>
              <CtlField label="Row">
                <div className="hvs-seg" role="group" aria-label="Row (select several)">
                  {[["selectable", "Selectable"], ["expandable", "Expandable"], ["rowView", "Action"], ["rowMenu", "More Actions"]].map(([key, label]) => {
                    const on = !!cfg[key];
                    const blocked = (key === "selectable" || key === "expandable") && cfg.size === "compact"; // Compact has no selection or expand column
                    const hint = { rowView: "Action: the View button in each row", rowMenu: "More Actions: the row menu (three dots) in each row" }[key];
                    return (
                      <button key={key} type="button" className="hvs-segbtn" aria-pressed={on} disabled={blocked}
                              title={blocked ? "Not available in Compact" : hint} onClick={() => set({ [key]: !on })}>{label}</button>
                    );
                  })}
                </div>
              </CtlField>
              <CtlField label="Column Config">
                <div className="hvs-seg" role="group" aria-label="Column Config">
                  {[["legacy", "Legacy"], ["latest", "Latest"]].map(([value, label]) => (
                    <button key={value} type="button" className="hvs-segbtn" aria-pressed={cfg.columnConfig === value}
                            title={value === "legacy" ? "Configure Columns with the Fixed, Visible and Hidden lists and Apply" : "Configure Columns as one list: check, pin and drag"}
                            onClick={() => set({ columnConfig: value })}>{label}</button>
                  ))}
                </div>
              </CtlField>
              <CtlField label="Data">
                <MenuButton variant="ghost" role="listbox" ariaLabel="Data source" value={cfg.dataset} minWidth={290} label={ds.label}
                            items={[
                              { heading: true, label: `Product specific: ${PRODUCTS.find((p) => p.id === cfg.product).label}` },
                              ...PRODUCT_DATASETS.map((d) => ({ value: d.id, label: d.label })),
                            ]}
                            onSelect={(it) => switchDataset(it.value)} />
              </CtlField>
              <CtlField label="Number of rows">
                <CtlSelect ariaLabel="Number of rows" value={dataRows.length}
                            options={ROW_COUNTS.map((n) => ({ value: n, label: String(n) }))}
                            onPick={(n) => {
                              setDataRows(ds.rows.slice(0, n));
                              // 3 and 5 rows start without pagination; 7 and 40 bring it back when it was only off because of that
                              set({ rowCount: n, ...(n <= 5 ? LIST_PATCH.none : listModeOf(cfg) === "none" ? LIST_PATCH.pagination : {}) });
                            }} />
              </CtlField>
              <CtlField label="Pagination">
                <CtlSelect ariaLabel="Pagination" value={listModeOf(cfg)}
                           options={LIST_MODES.map(([value, label, tag]) => ({ value, label, tag }))}
                           onPick={(v) => set(LIST_PATCH[v])} />
              </CtlField>
              <CtlField label="State">
                <CtlSelect ariaLabel="State" value={cfg.tableState}
                           options={STATES.map(([value, label]) => ({ value, label }))}
                           onPick={(v) => set({ tableState: v })} />
              </CtlField>
              {cfg.tableState === "error" && !errorShown && errorLeft > 0 && (
                <span className="hvs-dstatus" role="status">Error banner in {errorLeft} s, or click the table</span>
              )}
              <button type="button" className="hvt-btn" onClick={reset}>Reset settings</button>
            </div>
          </div>
          </section>


          <div className="hvs-canvasrow" ref={canvasRef} onClick={triggerError}>
            {(cfg.showGrid || rzActive) && (
              <div className="hvs-grid-overlay" style={{ width: cfg.gridCanvas }} aria-hidden="true">
                {Array.from({ length: GRID.columns }, (_, i) => (<i key={i} />))}
              </div>
            )}
          <div className="hvs-stage" ref={stageRef} style={{ width: tableWidth, maxWidth: cfg.widthMode === "grid" ? undefined : "100%", ...gridPlace }}>
            <div className={`hvs-slot${maxOn ? " is-max" : ""}`}>
            <DataTable
              key={`${resetKey}-${cfg.dataset}`}
              title={cfg.titleText ?? ds.title}
              columns={columns}
              rows={cfg.tableState === "empty" ? EMPTY_ROWS : dataRows}
              addLabel={ds.addLabel}
              loading={cfg.tableState === "loading"}
              error={cfg.tableState === "error" && errorShown ? { message: `Could not refresh ${ds.label.toLowerCase()}. The rows below may be out of date.`, onRetry: () => set({ tableState: "default" }), onDismiss: () => setErrorShown(false) } : null}
              emptyState={{ title: "No data found", message: `There are no ${ds.label.toLowerCase()} to show yet. Add one to get started.` }}
              initialSort={ds.sort}
              theme={cfg.theme}
              tokens={{ ...tokenStyle, ...layoutVars }}
              showTitle={cfg.showTitle}
              showFilterBar={cfg.showFilterBar}
              onFilterBarChange={(v) => set({ showFilterBar: v })}
              showPagination={cfg.showPagination}
              scrollbarHorizontal={cfg.scrollbarHorizontal}
              scrollbarVertical={effVScroll}
              visibleRows={effVisible}
              columnMinWidth={cfg.columnMinWidth}
              pinnedColumns={pinnedKeys}
              columnConfig={cfg.columnConfig}
              showMaximize={cfg.showMaximize}
              showMoreOptions={cfg.showMoreOptions}
              onMaximizeChange={(m) => { setMaxOn(m); setLast(m ? "Maximized" : "Restored"); }}
              density={cfg.size}
              onDensityChange={(v) => setSize(v)}
              onColumnsChange={(c) => setColConfig(c)}
              selectable={cfg.selectable}
              expandable={cfg.expandable}
              searchEnabled={cfg.searchEnabled}
              searchMode={cfg.searchMode}
              searchPlaceholder={cfg.searchPlaceholder}
              searchDebounceMs={cfg.searchDebounceMs}
              searchDisabled={cfg.searchDisabled}
              searchError={cfg.searchError ? cfg.searchErrorText : ""}
              searchRecent={SEARCH_RECENT[ds.id] || []}
              initialPageSize={effPageSize}
              onPageSizeChange={(n) => (rowsMode && cfg.showPagination ? set({ heightRows: n }) : set({ pageSize: n }))}
              pageSizeOptions={[...new Set([...STEP5, effPageSize])].sort((a, b) => a - b)}
              rowGap={cfg.rowGap}
              columnReorder={cfg.columnReorder}
              onColumnOrderChange={setColOrder}
              columnResize={cfg.columnResize}
              onColumnResize={setColWidths}
              filterPanelStyle={cfg.filterPanelStyle}
              filterUi={cfg.filterUi}
              editable={cfg.editable}
              showAdd={cfg.showAddButton}
              rowView={cfg.rowView}
              rowMenu={cfg.rowMenu}
              showFilterButton={cfg.showFilterButton}
              onRowsChange={(next, ch) => { if (cfg.tableState === "empty") { setDataRows([...next, ...dataRows]); set({ tableState: "default" }); } else setDataRows(next); setLast(`${ch.type} → ${ch.row ? (ch.row.name || ch.row.c1 || `row ${ch.row.id}`) : ""} (${next.length} rows)`); }}
              initialFilterModel={startModel}
              onFilterModelChange={setModel}
              onSelectionChange={(ids) => setLast(`${ids.length} selected`)}
              onBulkAction={(action, ids) => setLast(`${action} → ${ids.length} rows`)}
              onView={(r) => setLast(`View → ${r.name || `row ${r.id}`}`)}
              onMore={(r) => setLast(`More options → ${r.name || `row ${r.id}`}`)}
            />
            {!maxOn && ["l", "r"].map((side) => (
              <div key={side} className={`hvs-rz is-${side}${rzActive ? " is-active" : ""}`} role="slider" tabIndex={0}
                   aria-label="Table width in layout grid columns" aria-orientation="horizontal"
                   aria-valuemin={MIN_SPAN} aria-valuemax={GRID.columns} aria-valuenow={spanNow}
                   aria-valuetext={`${spanNow} of ${GRID.columns} columns, ${tableWidth}px`}
                   onPointerDown={rzDown} onPointerMove={rzMove} onPointerUp={rzUp} onPointerCancel={rzUp} onKeyDown={rzKey} />
            ))}
            {rzActive && <div className="hvs-rz-tip" role="status">{spanNow} / {GRID.columns} columns · {tableWidth}px</div>}
            {!maxOn && ["t", "b"].map((side) => (
              <div key={side} className={`hvs-rz hvs-rz-v is-${side}${rzvTip ? " is-active" : ""}`} role="slider" tabIndex={0}
                   aria-label="Table height in rows" aria-orientation="vertical"
                   aria-valuemin={MIN_ROWS} aria-valuemax={MAX_ROWS} aria-valuenow={rowsNow ?? undefined}
                   aria-valuetext={rowsNow ? `${rowsNow} rows` : "automatic height"}
                   onPointerDown={rzvDown} onPointerMove={rzvMove} onPointerUp={rzvUp} onPointerCancel={rzvUp} onKeyDown={rzvKey} />
            ))}
            {rzvTip && <div className="hvs-rz-tip is-v" role="status">{rzvTip.n} rows · {rzvTip.px}px</div>}
            </div>
          </div>
          </div>
        </main>
      </div>

      <footer className="hvs-footer">
        <p className="hvs-note hvs-last">Last action: {last}. Build {BUILD}.</p>
        <div className="hvs-readouts">
          <details className="hvs-details">
            <summary>Properties (global, component, features)</summary>
            <pre>{JSON.stringify(readout, null, 2)}</pre>
          </details>
          <details className="hvs-details">
            <summary>Data source</summary>
            <pre>{JSON.stringify({ dataset: ds.id, group: ds.group, state: cfg.tableState, rows: dataRows.length }, null, 2)}</pre>
          </details>
          <details className="hvs-details">
            <summary>Token overrides</summary>
            <pre>{JSON.stringify(cfg.tokens, null, 2)}</pre>
          </details>
          <details className="hvs-details">
            <summary>filterModel (MUI Data Grid format)</summary>
            <pre>{JSON.stringify(model, null, 2)}</pre>
          </details>
          <details className="hvs-details">
            <summary>Column order and widths</summary>
            <pre>{JSON.stringify({ order: colOrder || columns.map((c) => c.key), fixed: colConfig && colConfig.fixed ? colConfig.fixed : pinnedKeys, hidden: colConfig ? colConfig.hidden : [], widths: colWidths }, null, 2)}</pre>
          </details>
        </div>
      </footer>
      </>) : page === "tags" ? (
        <TagsBench theme={cfg.theme} onTheme={(v) => set({ theme: v })} />
      ) : (
        <SearchBench theme={cfg.theme} onTheme={(v) => set({ theme: v })} />
      )}
    </div>
  );
}
